// Disposable synthetic documents only. Requires Windows + Hancom Hangul 2024.
const fs=require('node:fs'),path=require('node:path'),os=require('node:os'),assert=require('node:assert/strict');
const {runPython}=require('../src/python.cjs'),{NativeDocuments}=require('../src/native-documents.cjs');
const root=path.resolve(__dirname,'..'),home=fs.mkdtempSync(path.join(os.tmpdir(),'narae-native-smoke-')),python=require('../src/runtime-python.cjs').resolvePython(root),native=new NativeDocuments(home,python);
fs.mkdirSync(path.join(home,'cache'));const doc=req=>runPython(python,home,'documents.py',req),live=req=>runPython(python,home,'live_hangul.py',req);
(async()=>{const results=[];try{for(const ext of ['hwpx','hwp']){const file=path.join(home,'native.'+ext);await doc({action:'create',path:file,blocks:[{type:'paragraph',text:'나래 한글 오피스 검증'},{type:'paragraph',text:'한 문단의 원문입니다.'},{type:'table',columns_mm:[70,70],rows:[[{text:'첫째 셀'},{text:'둘째 셀'}],[{text:'셋째 셀'},{text:'넷째 셀'}]]}]});const created=await doc({action:'inspect',path:file});assert.equal(created.tables.length,1);await native.openFile(file,{background:true});const before=await native.list(),pid=before.open_document_list.find(item=>item.local_path.toLowerCase()===file.toLowerCase()).pid;const read=await live({action:'read',path:file});await assert.rejects(live({action:'edit',path:file,liveRevision:'stale',operations:[{op:'replace_text',text:'한 문단의 원문입니다.',replacement:'거절되어야 합니다.'}],backupDir:path.join(home,'backups')}),/다시 읽/);const edited=await live({action:'edit',path:file,liveRevision:read.liveRevision,operations:[{op:'replace_text',text:'한 문단의 원문입니다.',replacement:'수정한 문단입니다.'},{op:'set_style',text:'수정한 문단입니다.',font_size:17,bold:true}],save:true,backupDir:path.join(home,'backups')});assert.match(edited.text,/수정한 문단입니다/);assert(edited.saved);const after=await native.list();assert.equal(after.open_document_list.find(item=>item.local_path.toLowerCase()===file.toLowerCase()).pid,pid);const style=await runPython(python,home,'hwp_native.py',{action:'read_styles',path:file,targets:[{text:'수정한 문단입니다.',occurrences:1,occurrence:0,line_id:'verification'}]});assert.equal(style.facts[0].properties.font_size,17);assert.equal(style.facts[0].properties.bold,true);await native.closeFile(file,true);await native.openFile(file,{background:true});const reopened=await live({action:'read',path:file});assert.match(reopened.text,/수정한 문단입니다/);await native.closeFile(file,true);const pdf=path.join(home,'cache/native-'+ext+'.pdf'),preview=await doc({action:'previewNativeHangul',path:file,target:pdf});assert(preview.source_unchanged);assert.equal(preview.pages,1);const image=await doc({action:'inspect',path:pdf,page:0});assert(image.image.length>100);results.push({format:ext,actualNativeEdit:true,style17Bold:true,sameApplicationDuringEdit:true,savedReopen:true,pdfPages:preview.pages,sourceUnchangedDuringPreview:true,nativeVersion:preview.native_version,nativeExecutable:preview.native_executable});}console.log(JSON.stringify({passed:true,home,results}));fs.writeFileSync(path.join(home,'result.json'),JSON.stringify({passed:true,results},null,2));}finally{const info=await native.list().catch(()=>({open_document_list:[]}));for(const item of info.open_document_list)if(item.local_path.startsWith(home))await native.closeFile(item.local_path,true).catch(()=>{});native.close();}})().catch(error=>{console.error(error);process.exitCode=1;});
